SELECT ROUND(AVG(rental_count)::numeric, 2) AS avg_rentals_per_customer
FROM (
  SELECT customer_id, COUNT(*) AS rental_count
  FROM rental
  GROUP BY customer_id
) t;

SELECT COUNT(*) AS films_longer_than_average
FROM film
WHERE length > (SELECT AVG(length) FROM film);

SELECT COUNT(*) AS rentals_2025
FROM rental
WHERE rental_date >= '2025-01-01' AND rental_date < '2026-01-01';

SELECT COUNT(DISTINCT film_id) AS films_count
FROM film_actor
WHERE actor_id = 1;

SELECT COUNT(DISTINCT customer_id) AS num_customers
FROM rental
WHERE customer_id IS NOT NULL;

SELECT ROUND(AVG(diff), 2) AS avg_days_between_rentals
FROM (
  SELECT (julianday(rental_date) - julianday(LAG(rental_date) OVER (PARTITION BY customer_id ORDER BY rental_date))) AS diff
  FROM rental
) sub
WHERE diff IS NOT NULL;

SELECT ROUND(AVG(diff_days)::numeric, 2) AS avg_days_between_rentals
FROM (
  SELECT (EXTRACT(EPOCH FROM (rental_date::timestamptz - LAG(rental_date::timestamptz) OVER (PARTITION BY customer_id ORDER BY rental_date))) / 86400.0) AS diff_days
  FROM rental
) sub
WHERE diff_days IS NOT NULL;

